local DRY_RUN = true local FLIP_180 = true local DELETE_OLD = true local HEIGHT_OFFSET = 0 local FORWARD_OFFSET = 0 local FOLDER_NAME = "Booths" local BACKUP_FOLDER = "OldBooths_Backup" local TEMPLATE_NAME = nil local W = game:GetService("Workspace") local Sel = game:GetService("Selection") local function isNew(m) if not m:IsA("Model") then return false end local d = m:FindFirstChild("Display") if not d then return false end return d:FindFirstChild("BoothOwner") ~= nil and d:FindFirstChild("SurfaceGui") ~= nil end local function isOld(m) if not m:IsA("Model") then return false end if not m:FindFirstChild("Banner") then return false end if isNew(m) then return false end return true end local function bounds(m) local a, b, c = math.huge, math.huge, math.huge local d, e, f = -math.huge, -math.huge, -math.huge local got = false for _, p in ipairs(m:GetDescendants()) do if p:IsA("BasePart") then got = true local s = p.Size local sx, sy, sz = s.X / 2, s.Y / 2, s.Z / 2 local x, y, z, r00, r01, r02, r10, r11, r12, r20, r21, r22 = p.CFrame:components() local ex = math.abs(r00) * sx + math.abs(r01) * sy + math.abs(r02) * sz local ey = math.abs(r10) * sx + math.abs(r11) * sy + math.abs(r12) * sz local ez = math.abs(r20) * sx + math.abs(r21) * sy + math.abs(r22) * sz if x - ex < a then a = x - ex end if y - ey < b then b = y - ey end if z - ez < c then c = z - ez end if x + ex > d then d = x + ex end if y + ey > e then e = y + ey end if z + ez > f then f = z + ez end end end if not got then return nil end return Vector3.new(a, b, c), Vector3.new(d, e, f) end local function moveModel(m, t) for _, p in ipairs(m:GetDescendants()) do if p:IsA("BasePart") then p.CFrame = t * p.CFrame end end end local function flatLook(cf) local l = cf.LookVector local v = Vector3.new(l.X, 0, l.Z) if v.Magnitude < 0.001 then return Vector3.new(0, 0, -1) end return v.Unit end local template = nil if TEMPLATE_NAME then for _, x in ipairs(game:GetDescendants()) do if x.Name == TEMPLATE_NAME and isNew(x) then template = x break end end else local pool = {} for _, where in ipairs({ game:GetService("ServerStorage"), game:GetService("ReplicatedStorage"), game:GetService("Lighting"), W }) do for _, x in ipairs(where:GetDescendants()) do if isNew(x) then table.insert(pool, x) end end end template = pool[1] end if not template then warn("[Booths] No boothgood template found. Insert boothgood.rbxm first.") return end local old = {} for _, x in ipairs(W:GetDescendants()) do if isOld(x) then table.insert(old, x) end end print("========================================") print("[Booths] template: " .. template:GetFullName()) print("[Booths] old booths found: " .. #old) print("[Booths] DRY_RUN: " .. tostring(DRY_RUN)) print("========================================") if #old == 0 then warn("[Booths] Nothing to replace.") return end local tDisp = template:FindFirstChild("Display") if not tDisp then warn("[Booths] Template has no Display part.") return end local tMin = select(1, bounds(template)) if not tMin then warn("[Booths] Template has no parts.") return end local rise = tDisp.Position.Y - tMin.Y local folder = W:FindFirstChild(FOLDER_NAME) local backup = W:FindFirstChild(BACKUP_FOLDER) if not DRY_RUN then if not folder then folder = Instance.new("Folder") folder.Name = FOLDER_NAME folder.Parent = W end if not DELETE_OLD and not backup then backup = Instance.new("Folder") backup.Name = BACKUP_FOLDER backup.Parent = W end end if template:IsDescendantOf(folder) then warn("[Booths] Move the template OUT of Workspace." .. FOLDER_NAME .. " first.") return end local made = {} local skipped = 0 for i, b in ipairs(old) do local banner = b:FindFirstChild("Banner") local lo = select(1, bounds(b)) if not banner or not lo then skipped = skipped + 1 warn(string.format("[Booths] #%d skipped (no Banner or no parts).", i)) else local outward = flatLook(banner.CFrame) local facing = outward if FLIP_180 then facing = outward * -1 end local pos = Vector3.new(banner.Position.X, lo.Y + rise + HEIGHT_OFFSET, banner.Position.Z) + outward * FORWARD_OFFSET local goal = CFrame.new(pos, pos + facing) print(string.format("[Booths] #%2d %s -> (%.1f, %.1f, %.1f)", i, b.Name, pos.X, pos.Y, pos.Z)) if not DRY_RUN then local copy = template:Clone() copy.Name = "Booth" local cd = copy:FindFirstChild("Display") moveModel(copy, goal * cd.CFrame:Inverse()) copy.Parent = folder table.insert(made, copy) if DELETE_OLD then b:Destroy() else b.Parent = backup end end end end print("========================================") if DRY_RUN then print(string.format("[Booths] DRY RUN: would replace %d, skip %d.", #old - skipped, skipped)) print("[Booths] Change DRY_RUN to false at the very start, then run again.") else print(string.format("[Booths] Replaced %d, skipped %d.", #made, skipped)) print("[Booths] New booths are in Workspace." .. FOLDER_NAME) print("[Booths] Ctrl+Z undoes the whole run.") pcall(function() Sel:Set(made) end) end print("========================================")
